<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TPIR Student Register</title><style>body{font-family:Arial,sans-serif;color:#111;margin:24px}h1,h2,p{text-align:center;margin:4px}.toolbar{text-align:right;margin-bottom:18px}button{padding:9px 16px;background:#123b73;color:white;border:0;border-radius:6px}table{width:100%;border-collapse:collapse;margin-top:20px;font-size:11px}th,td{border:1px solid #bbb;padding:7px;text-align:left}th{background:#eef2f7}.muted{color:#555;font-size:11px}@media print{.toolbar{display:none}body{margin:8mm}@page{size:A4 landscape;margin:8mm}tr{break-inside:avoid}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save PDF</button></div><h1>TMSS POLYTECHNIC INSTITUTE</h1><h2>Rangpur · TPIR</h2><p>Student Register · Total: <?php echo e(count($students)); ?></p><table><thead><tr><th>#</th><th>Roll</th><th>Student Name</th><th>Technology</th><th>Semester</th><th>Session</th><th>Shift</th><th>Mobile</th><th>Status</th></tr></thead><tbody><?php $__currentLoopData = $students; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $i=>$s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><?php echo e($i+1); ?></td><td><?php echo e($s->student_id); ?></td><td><?php echo e($s->name); ?></td><td><?php echo e($s->technology); ?></td><td><?php echo e($s->semester); ?></td><td><?php echo e($s->session); ?></td><td><?php echo e($s->shift); ?></td><td><?php echo e($s->phone); ?></td><td><?php echo e($s->status); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table><p class="muted" style="margin-top:20px">Printed on <?php echo e(now()->format('d M Y h:i A')); ?></p></body></html>
